head.script:
scwin.gEmpNo;
scwin.gAcptNo; // 접수번호
scwin.gFormKorNm; // 서식명
scwin.gTitle; // 공시제목

scwin.gProcsStatCd;
scwin.gTrdHaltMsg;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.libRoundPanel.PanelToGroupBox(pnl_1);

        // 가우스헤더 셋팅
        const sbmOptions = {
            id : "sbm_dts_titleinfo",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_titleinfo=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        // 부모창의 데이타 셋팅하기
        scwin.setParamData();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10003.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_modify_OnSuccess
 * @description modify On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_modify_OnSuccess = async function() {
    try {
        await $c.win.alert("성공적으로 저장되었습니다.");
        await $c.win.closePopup();
        // 부모창 reload 처리해야함
        // frame.Provider("/frame_head").fn_HeadRead() ;
        $c.frame.path("../../frame_head").fn_HeadRead();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10003.trs_modify_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_modify_OnFail
 * @description modify On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_modify_OnFail = async function() {
    try {
        await $c.win.alert('trs_modify.OnFail() :' + trs_modify.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10003.trs_modify_OnFail" });
    }
};

/**
 * @method
 * @name btn_Cancel_onclick
 * @description 「취소」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Cancel_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10003.btn_Cancel_onclick" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        await scwin.modifyDsclTitle();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10003.btn_Save_onclick" });
    }
};

/**
 * @method
