///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name modifyDsclTitle
 * @description 수정하기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modifyDsclTitle = async function() {
    if ($c.stf.checkMaxLength(txb_Title, 200, '공시제목') === false) {
        return;
    }
    if (await scwin.getProcsSate(scwin.gAcptNo) === false) {
        return false;
    } else {
        const vNewTitle = txb_Title.getValue();
        dts_titleinfo.insertRow();
        dts_titleinfo.setCellData(1, "ACPT_NO", scwin.gAcptNo);
        dts_titleinfo.setCellData(1, "DISCLS_TITLE", vNewTitle);
        dts_titleinfo.setCellData(1, "EMP_NO", scwin.gEmpNo);
        dts_titleinfo.setCellData(1, "DISCLS_DUTY_TP_CD", js_duty_tp_cd);
        const vAnswer = confirm('공시제목을  변경하시겠습니까?');
        if (vAnswer === true) {
            trs_modify.KeyName = "toinb_dataid4";
            const sbmOptions = {
                id : "sbm_trs_modify",
                action : "/DisclosureStudy.do",
                ref : "dts_titleinfo",
                target : "trs_modify=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        }
    }
};

/**
 * @method
 * @name getProcsSate
 * @description 처리상태 조회하기
 * @param {*} gAcptNo gAcptNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getProcsSate = async function(gAcptNo) {
    const sbmOptions = {
        id : "sbm_dts_procs_stat",
        action : "/Viewer.do",
        ref : "",
        target : "dts_procs_stat=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const vPROCS_STAT_CD = dts_procs_stat.getCellData(1, "PROCS_STAT_CD");
    const vPROCS_STAT_NM = dts_procs_stat.getCellData(1, "PROCS_STAT_NM");
    const vPROCS_DDTM = dts_procs_stat.getCellData(1, "PROCS_DDTM");
    const vBLOCK_YN = dts_procs_stat.getCellData(1, "BLOCK_YN");
    if (vBLOCK_YN === 'Y') {
        await $c.win.alert(scwin.gTrdHaltMsg);
        return false;
    }
    if (scwin.gProcsStatCd !== vPROCS_STAT_CD) {
        await $c.win.alert("본 공시가 " + vPROCS_DDTM + "에  이미 [" + vPROCS_STAT_NM + "] 처리가 되었습니다.");
        window.open('', '_self', '');
        window.close();
        return false;
    } else {
        return true;
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setParamData
 * @description 부모창의 데이타 셋팅하기
 * @returns {void}
 * @hidden N
 */
scwin.setParamData = function() {
    /*
		gAcptNo = frame.Provider("../").dts_AcptProcs.NameString(1, 'ACPT_NO');
		gFormKorNm = frame.Provider("../").dts_AcptProcs.NameString(1, 'FORM_KOR_NM');
		gTitle = frame.Provider("../").dts_AcptProcs.NameString(1, 'DISCLS_TITLE');
     */
    //  frame.Provider("/frame_head") 상황에 따라서 바뀌네..?
    scwin.gAcptNo = $c.frame.path("../../frame_head").dts_AcptProcs.getCellData(1, 'ACPT_NO');
    scwin.gFormKorNm = $c.frame.path("../../frame_head").dts_AcptProcs.getCellData(1, 'FORM_KOR_NM');
    scwin.gTitle = $c.frame.path("../../frame_head").dts_AcptProcs.getCellData(1, 'DISCLS_TITLE');
    txb_FormKorNm_Org.setValue(scwin.gFormKorNm);
    txb_Title.setValue(scwin.gTitle);
    scwin.gProcsStatCd = $c.frame.path("../../frame_head").scwin.gProcsStatCd;
    scwin.gTrdHaltMsg = $c.frame.path("../../frame_head").scwin.gTrdHaltMsg;
    scwin.gEmpNo = js_emp_no; // 세션정보

};
